{% set assignee_name = frappe.db.get_value("User", doc.allocated_to, "full_name") or doc.allocated_to %}
{% set assigner_user = doc.assigned_by or doc.owner %}
{% set assigner_name = frappe.db.get_value("User", assigner_user, "full_name") or assigner_user %}

{% if doc.reference_type and doc.reference_name %}
  {% set form_url = frappe.utils.get_url_to_form(doc.reference_type, doc.reference_name) %}
{% else %}
  {% set form_url = frappe.utils.get_url() ~ doc.get_url() %}
{% endif %}

{% set priority = doc.priority or "Normal" %}
{% set priority_th = "ปกติ" %}
{% if priority in ["High", "Urgent"] %}
  {% set priority_th = "สูง" %}
{% elif priority == "Medium" %}
  {% set priority_th = "ปานกลาง" %}
{% elif priority == "Low" %}
  {% set priority_th = "ต่ำ" %}
{% endif %}

<!-- ===== English ===== -->
<p>Hello {{ assignee_name }},</p>

<p>You've been assigned: <b>{{ doc.reference_type }} {{ doc.reference_name }}</b>
by {{ assigner_name }}.</p>

<p><a href="{{ form_url }}">Open the document</a></p>

{% if doc.description %}
  <p><b>Notes:</b> {{ doc.description }}</p>
{% endif %}

<p>Priority: {{ priority }}</p>

<hr>

<!-- ===== ภาษาไทย ===== -->
<p>เรียนคุณ {{ assignee_name }},</p>

<p>คุณได้รับมอบหมายงาน: <b>{{ doc.reference_type }} {{ doc.reference_name }}</b>
โดย {{ assigner_name }}.</p>

<p><a href="{{ form_url }}">เปิดเอกสาร</a></p>

{% if doc.description %}
  <p><b>หมายเหตุ:</b> {{ doc.description }}</p>
{% endif %}

<p>ลำดับความสำคัญ: {{ priority_th }}</p>
